/* Spanish question bank — Who Wants to Be a Language Millionaire? GCSE Spanish (AQA 8692, Pearson Edexcel 1SP1), one SSM.addBank call per unit in taxonomy order. */
SSM.addBank('spanish', 'P1', [
  ["id1","F",1,"V","What does “el hermano” mean?",["the brother","the father","the cousin","the uncle"],"The word hermano means brother; padre is father and primo is cousin."],
  ["id1","F",1,"V","How do you say “the grandmother” in Spanish?",["la abuela","la tía","la madre","la prima"],"The word abuela is grandmother; tía is aunt and prima is a female cousin."],
  ["id1","F",2,"V","What does “tiene el pelo rizado” mean?",["he has curly hair","he has straight hair","he has long hair","he has fair hair"],"The adjective rizado means curly; liso is straight and largo is long."],
  ["id1","F",2,"G","Complete: Mi madre es muy ___ .",["simpática","simpático","simpáticos","simpáticas"],"Adjectives agree with the noun: madre is feminine singular, so simpática."],
  ["id1","F",3,"T","Which is the correct translation of “My sister has blue eyes”?",["Mi hermana tiene los ojos azules.","Mi hermana es los ojos azules.","Mi hermana tiene los ojos azul.","Mi hermana tiene las ojos azules."],"With eyes, Spanish uses tener + los ojos, and azul becomes azules in the plural."],
  ["id1","F",3,"G","Complete: Mis primos ___ altos y delgados.",["son","están","es","tienen"],"Because height and build are lasting characteristics, they use ser; primos is plural, so son."],
  ["id1","F",4,"R","Read: «Me llamo Pablo. Soy hijo único, pero tengo dos primas que viven en Sevilla.» What do we learn about Pablo?",["He has no brothers or sisters.","He has two sisters in Seville.","He is the only cousin in the family.","He lives in Seville with his cousins."],"The phrase hijo único means only child; the two primas are his cousins."],
  ["id1","H",4,"V","What does “Mi padrastro es calvo y lleva gafas” mean?",["My stepfather is bald and wears glasses.","My godfather is bald and wears glasses.","My stepfather is fat and wears glasses.","My stepfather is bald and has a beard."],"The word padrastro is stepfather (padrino is godfather), and calvo means bald."],
  ["id1","H",5,"G","Complete: Mi abuela ___ muy guapa cuando era joven, pero ahora ___ cansada.",["era / está","era / es","estaba / es","es / está"],"A lasting description in the past uses the imperfect of ser (era), while a temporary state now uses estar (está)."],
  ["id1","H",5,"T","Which is the correct translation of “My brother is older than me, but less tall”?",["Mi hermano es mayor que yo, pero menos alto.","Mi hermano es mayor que mí, pero menos alto.","Mi hermano está mayor que yo, pero menos alto.","Mi hermano es mayor de yo, pero menos alto."],"After que in a comparison Spanish uses the subject pronoun yo, and mayor already means older."],

  ["id2","F",1,"V","How do you say “the friend” (a girl) in Spanish?",["la amiga","el amigo","la novia","la vecina"],"The feminine form amiga ends in -a; novia means girlfriend and vecina neighbour."],
  ["id2","F",1,"V","What does “el novio” mean?",["the boyfriend","the neighbour","the son","the husband"],"The word novio means boyfriend (or groom at a wedding); marido is husband."],
  ["id2","F",2,"T","What does “Me llevo bien con mi hermana” mean?",["I get on well with my sister.","I take my sister with me.","I argue with my sister.","I look like my sister."],"The reflexive verb llevarse bien con means to get on well with someone."],
  ["id2","F",2,"V","Which phrase means “we argue” (we fight)?",["nos peleamos","nos llevamos","nos reímos","nos ayudamos"],"The verb pelearse means to fight or argue; llevarse means to get on and reírse to laugh."],
  ["id2","F",3,"G","Complete: Mi mejor amigo ___ llama Javier.",["se","me","te","le"],"The verb llamarse is reflexive, so the he/she form is se llama."],
  ["id2","F",3,"T","Which is the correct translation of “A good friend is loyal and honest”?",["Un buen amigo es leal y honesto.","Un bueno amigo es leal y honesto.","Un buen amigo está leal y honesto.","Una buena amigo es leal y honesto."],"The adjective bueno shortens to buen before a masculine singular noun, and personality uses ser."],
  ["id2","F",4,"R","Read: «Conocí a Marta en el colegio. Es muy graciosa, pero a veces es un poco egoísta.» What is Marta’s negative quality?",["She can be selfish.","She can be shy.","She is not very funny.","She is sometimes rude."],"The adjective egoísta means selfish; graciosa means funny."],
  ["id2","H",4,"V","What does “Mi amiga siempre me apoya cuando tengo problemas” mean?",["My friend always supports me when I have problems.","My friend always leans on me when I have problems.","My friend always calls me when I have problems.","My friend always annoys me when I have problems."],"The verb apoyar means to support; me is the object pronoun placed before the verb."],
  ["id2","H",5,"G","Complete: Mi novio y yo ___ desde hace dos años.",["salimos juntos","salíamos juntos","salimos juntas","salir juntos"],"With desde hace Spanish uses the present tense for something still going on, and a mixed pair takes masculine juntos."],
  ["id2","H",5,"T","Which is the correct translation of “When I was little, I used to play with my neighbour every day”?",["Cuando era pequeño, jugaba con mi vecino todos los días.","Cuando fui pequeño, jugué con mi vecino todos los días.","Cuando era pequeño, jugué con mi vecino todos los días.","Cuando estaba pequeño, jugaba con mi vecino todos los días."],"The imperfect describes how things were and what you used to do: era pequeño, jugaba."]
]);

SSM.addBank('spanish', 'P2', [
  ["he1","F",1,"V","What does “el pescado” mean?",["the fish","the meat","the chicken","the cake"],"The word pescado is fish as food (a live fish is un pez); carne is meat."],
  ["he1","F",1,"V","How do you say “the water” in Spanish?",["el agua","el té","el zumo","el vino"],"The word agua is feminine but takes el because it starts with a stressed a-; té is tea."],
  ["he1","F",2,"V","What does “me gustan las verduras” mean?",["I like vegetables","I like fruit","I don’t like vegetables","I liked the vegetables"],"The verb gustan is plural because las verduras is plural; verduras are vegetables."],
  ["he1","F",2,"V","Which word means “I have breakfast”?",["desayuno","ceno","como","meriendo"],"The verb desayunar is to have breakfast; cenar is to have dinner and merendar to have a snack."],
  ["he1","F",3,"G","Complete: No me ___ los caramelos porque son demasiado dulces.",["gustan","gusta","gusto","gustas"],"The verb agrees with what is liked: los caramelos is plural, so gustan."],
  ["he1","F",3,"T","Which is the correct translation of “I should eat less fast food”?",["Debería comer menos comida rápida.","Debería comer más comida rápida.","Debería beber menos comida rápida.","Debería come menos comida rápida."],"The conditional debería means should; menos is less and más is more."],
  ["he1","F",4,"R","Read: «Soy vegetariana desde hace un año. Como mucha fruta, pero nunca como carne ni pescado.» What does she never eat?",["meat or fish","fruit or vegetables","meat or eggs","fish or cheese"],"The phrase nunca … ni means never … or; carne is meat and pescado fish."],
  ["he1","H",4,"V","What does “Hay que evitar la comida grasienta” mean?",["You have to avoid greasy food.","You have to try greasy food.","There is greasy food.","You have to avoid sweet food."],"The phrase hay que means one has to, evitar is to avoid and grasienta is greasy."],
  ["he1","H",5,"G","Complete: Anoche mi hermano ___ demasiado y luego se sintió mal.",["comió","comía","come","comido"],"A single completed action at a set time (anoche) takes the preterite: comió."],
  ["he1","H",5,"T","Which is the correct translation of “I used to drink a lot of fizzy drinks, but now I drink water”?",["Antes bebía muchos refrescos, pero ahora bebo agua.","Antes bebí muchos refrescos, pero ahora bebo agua.","Antes bebía muchas refrescos, pero ahora bebo agua.","Antes bebía muchos refrescos, pero ahora bebí agua."],"The imperfect bebía describes a past habit, and refresco is masculine, so muchos."],

  ["he2","F",1,"V","What does “sano” mean?",["healthy","tired","ill","strong"],"The adjective sano means healthy; enfermo is ill and cansado tired."],
  ["he2","F",1,"V","How do you say “to sleep” in Spanish?",["dormir","despertar","descansar","soñar"],"The verb dormir means to sleep; descansar is to rest and soñar to dream."],
  ["he2","F",2,"V","What does “hago ejercicio” mean?",["I do exercise","I did exercise","I make an effort","I hate exercise"],"The form hago is the I form of hacer, and hacer ejercicio means to exercise."],
  ["he2","F",2,"V","What does “me duele la pierna” mean?",["my leg hurts","my arm hurts","my foot hurts","my leg is broken"],"The verb doler works like gustar: me duele la pierna is my leg hurts; pierna is leg."],
  ["he2","F",3,"G","Complete: Para estar en forma, ___ entrenar tres veces a la semana.",["hay que","hay","tengo","es que"],"The phrase hay que + infinitive means one must; hay on its own means there is."],
  ["he2","F",3,"T","Which is the correct translation of “I don’t smoke because it is bad for your health”?",["No fumo porque es malo para la salud.","No fumo porque está malo para la salud.","No fumo porque es malo por la salud.","No fumo porque es mala para la salud."],"The phrase ser malo para means to be bad for; para shows who or what is affected."],
  ["he2","F",4,"R","Read: «Antes jugaba al fútbol, pero ahora prefiero el yoga porque es más relajante.» Why does the writer prefer yoga now?",["It is more relaxing.","It is more fun.","It is less tiring.","It is cheaper."],"The adjective relajante means relaxing; antes jugaba shows football was in the past."],
  ["he2","H",4,"V","What does “Me acuesto temprano para no estar agotado” mean?",["I go to bed early so as not to be exhausted.","I get up early so as not to be exhausted.","I go to bed late so as not to be bored.","I go to bed early so as not to be stressed."],"The verb acostarse is to go to bed (levantarse is to get up), and agotado means exhausted."],
  ["he2","H",5,"G","Complete: Llevo dos meses ___ al gimnasio y ya me siento mejor.",["yendo","ir","fui","voy"],"The structure llevar + time + gerund means to have been doing something; the gerund of ir is yendo."],
  ["he2","H",5,"T","Which is the correct translation of “I have just played tennis and I’m very tired”?",["Acabo de jugar al tenis y estoy muy cansado.","Acabo de jugar al tenis y soy muy cansado.","Acabé jugar al tenis y estoy muy cansado.","Acabo jugar al tenis y estoy muy cansado."],"The phrase acabar de + infinitive means to have just done something, and tiredness is a state, so estar."]
]);

SSM.addBank('spanish', 'P3', [
  ["ed1","F",1,"V","What does “la asignatura” mean?",["the school subject","the signature","the timetable","the classroom"],"The word asignatura is a school subject; a signature is una firma."],
  ["ed1","F",1,"V","How do you say “the library” in Spanish?",["la biblioteca","la librería","el laboratorio","la oficina"],"The false friend librería is a bookshop; a library is la biblioteca."],
  ["ed1","F",2,"V","What does “los deberes” mean?",["homework","the rules","the exams","the lessons"],"The plural los deberes means homework; las normas are rules."],
  ["ed1","F",2,"G","Which phrase means “my favourite subject”?",["mi asignatura preferida","mi asignatura preferido","mi preferida asignatura","mis asignatura preferida"],"Adjectives usually follow the noun and agree with it: asignatura is feminine, so preferida."],
  ["ed1","F",3,"G","Complete: Las ciencias ___ más difíciles que el inglés.",["son","es","están","somos"],"Because las ciencias is plural, ser becomes son; comparisons of quality use ser."],
  ["ed1","F",3,"T","Which is the correct translation of “We have to wear a uniform”?",["Tenemos que llevar uniforme.","Tenemos llevar uniforme.","Tenemos que llevamos uniforme.","Hay que llevamos uniforme."],"The structure tener que + infinitive means to have to; llevar is to wear."],
  ["ed1","F",4,"R","Read: «En mi instituto hay muchas normas. No se puede usar el móvil en clase y es obligatorio llevar corbata.» What is NOT allowed?",["using a phone in lessons","wearing a tie","arriving late to class","eating in lessons"],"The phrase no se puede means you can’t; a corbata (tie) is compulsory, not banned."],
  ["ed1","H",4,"V","What does “Saqué buenas notas en los exámenes” mean?",["I got good marks in the exams.","I took good notes in the exams.","I need good marks in the exams.","I will get good marks in the exams."],"The phrase sacar buenas notas means to get good marks; saqué is the preterite I form."],
  ["ed1","H",5,"G","Complete: Ayer el profesor nos ___ muchos deberes.",["dio","dió","daba","dimos"],"The preterite of dar is irregular: di, diste, dio, with no accent on dio."],
  ["ed1","H",5,"R","Read: «Me encanta el dibujo, pero lo que más me molesta es que hay demasiados exámenes.» What annoys the writer most?",["There are too many exams.","Art is too difficult.","There is too much homework.","There are not enough art lessons."],"The phrase lo que más me molesta means what annoys me most; demasiados means too many."],

  ["ed2","F",1,"V","What does “el trabajo” mean?",["the job","the journey","the office","the boss"],"The word trabajo means work or job; jefe is boss and oficina office."],
  ["ed2","F",1,"V","How do you say “the nurse” (a woman) in Spanish?",["la enfermera","la enferma","la médica","la camarera"],"The word enfermera is a nurse; enferma means a sick woman and camarera is waitress."],
  ["ed2","F",2,"V","What does “quiero ser abogado” mean?",["I want to be a lawyer","I want to be a doctor","I wanted to be a lawyer","I want to be a teacher"],"The noun abogado is lawyer, and after ser jobs take no article."],
  ["ed2","F",2,"V","Which phrase means “part-time job”?",["trabajo a tiempo parcial","trabajo a tiempo completo","trabajo de tiempo libre","trabajo por partes"],"The phrase a tiempo parcial means part-time; a tiempo completo is full-time."],
  ["ed2","F",3,"G","Complete: Mi madre es ___ .",["profesora","una profesora","profesor","profesoras"],"After ser, jobs take no article, and the noun agrees with madre: profesora."],
  ["ed2","F",3,"T","Which is the correct translation of “In the future I would like to work abroad”?",["En el futuro me gustaría trabajar en el extranjero.","En el futuro me gusta trabajar en el extranjero.","En el futuro me gustaría trabajo en el extranjero.","En el futuro me gustaría trabajar en el extraño."],"The conditional me gustaría means I would like, followed by an infinitive; en el extranjero is abroad."],
  ["ed2","F",4,"R","Read: «Trabajo los sábados en una tienda de ropa. Gano poco, pero mis compañeros son muy amables.» What is the drawback of the job?",["The pay is low.","The colleagues are unfriendly.","The hours are long.","It is only on Saturdays."],"The phrase gano poco means I earn little; amables means kind."],
  ["ed2","H",4,"V","What does “Busco un empleo bien pagado con buenas perspectivas” mean?",["I’m looking for a well-paid job with good prospects.","I’m looking for a well-paid job with good friends.","I found a well-paid job with good prospects.","I’m looking for an easy job with good prospects."],"The verb buscar means to look for; empleo is job and bien pagado well paid."],
  ["ed2","H",5,"G","Complete: Después de ___ el bachillerato, voy a ir a la universidad.",["terminar","termino","terminando","terminé"],"After a preposition such as después de, Spanish uses the infinitive: después de terminar."],
  ["ed2","H",5,"T","Which is the correct translation of “I will go to university because I want to be an engineer”?",["Iré a la universidad porque quiero ser ingeniero.","Iría a la universidad porque quiero ser ingeniero.","Iré a la universidad porque quiero estar ingeniero.","Iré a la universidad porque quise ser ingeniero."],"The future of ir is iré (iría means I would go), and jobs use ser with no article."]
]);

